print "Rendering Shadow pass %s.z" %(Name)
ri.Begin("__render")
ri.Display(Name+".z", "zfile", "z")
ri.Clipping(1,10)
# Specify PAL resolution 1:1 pixel Aspect ratio
ri.Format(512,512,1)
