static void namesplit(TCHAR *s)
{
	int l;

	l = _tcslen(s) - 1;
	while (l >= 0) {
		if (s[l] == '.')
			s[l] = 0;
		if (s[l] == '\\' || s[l] == '/' || s[l] == ':' || s[l] == '?') {
			l++;
			break;
		}
		l--;
	}
	if (l > 0)
		memmove(s, s + l, (_tcslen(s + l) + 1) * sizeof (TCHAR));
}

